export type WindowPlay = {
  phase: PlayPhase;
  t: number;
  target: PlayTarget;
  x: number;
  lift: number;
  rot: number;
  anim: PlayAnim;
  facing: 1 | -1;
  from: PlayPoint;
  to: PlayPoint;
  abort?: boolean;
  hopIndex?: number;
};

export type PlayFlags = {
  asleep?: boolean;
  hidden?: boolean;
  leaving?: boolean;
  cmd?: string;
  card?: boolean;
};

function clamp(n: number, a: number, b: number) {
  return Math.max(a, Math.min(b, n));
}

function smoothstep(t: number) {
  const x = Math.max(0, Math.min(1, t));
  return x * x * (3 - 2 * x);
}

