export function thumpStampPath(u: number) {
  const t = Math.max(0, Math.min(1, u));
  if (t < 0.45) {
    const s = t / 0.45;
    return { lift: 8 * Math.sin(s * Math.PI * 0.5), rot: -7 * s };
  }
  if (t < 0.62) {
    const s = (t - 0.45) / 0.17;
    return { lift: 8 * (1 - s), rot: -7 * (1 - s) };
  }
  return { lift: 0, rot: 0 };
}

