export function bowDipPath(u: number) {
  const t = Math.max(0, Math.min(1, u));
  if (t < 0.38) {
    const s = t / 0.38;
    const dip = s * s * (3 - 2 * s);
    return { lift: -6 * dip || 0, rot: 14 * dip };
  }
  if (t < 0.55) {
    return { lift: -6, rot: 14 };
  }
  const s = (t - 0.55) / 0.45;
  const up = s * s * (3 - 2 * s);
  return { lift: -6 * (1 - up) || 0, rot: 14 * (1 - up) };
}

